package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.Zero
var WsBranchTot decimal.Decimal = decimal.Zero
var WsGrandTot decimal.Decimal = decimal.Zero
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var curRec LedgerRec
var inputLines []string
var inputIdx int
var inputDone bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmt(field string) decimal.Decimal {
	// field length 7, digits only, implied V99
	var v int64 = 0
	for i := 0; i < len(field); i++ {
		c := field[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else if c == ' ' {
			// treat space as 0? shift?
			// COBOL numeric DISPLAY with spaces: treat as zero digit
			v = v * 10
		} else if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		} else {
			v = v * 10
		}
	}
	return decimal.New(v, -2)
}

func storeBal(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	c := t.Shift(2).IntPart()
	mod := int64(1000000000)
	c = c % mod
	return decimal.New(c, -2)
}

func storeTot(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	c := t.Shift(2).IntPart()
	mod := int64(100000000000)
	c = c % mod
	return decimal.New(c, -2)
}

func formatAmt(d decimal.Decimal) string {
	t := d.Truncate(2)
	c := t.Shift(2).IntPart()
	if c < 0 {
		c = -c
	}
	frac := c % 100
	integ := (c / 100) % 100000
	// 5 digits
	digits := make([]byte, 5)
	tmp := integ
	for i := 4; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	// pattern: Z Z , Z Z 9
	pat := []byte{'Z', 'Z', ',', 'Z', 'Z', '9'}
	out := make([]byte, 0, 6)
	di := 0
	printed := false
	for _, p := range pat {
		if p == ',' {
			if printed {
				out = append(out, ',')
			} else {
				out = append(out, ' ')
			}
		} else {
			dgt := digits[di]
			di++
			if p == '9' {
				out = append(out, '0'+dgt)
				if dgt != 0 {
					printed = true
				}
			} else {
				if dgt != 0 {
					out = append(out, '0'+dgt)
					printed = true
				} else {
					if printed {
						out = append(out, '0')
					} else {
						out = append(out, ' ')
					}
				}
			}
		}
	}
	// decimal part
	fracStr := fmt.Sprintf(".%02d", frac)
	return string(out) + fracStr
}

func formatBal(d decimal.Decimal) string {
	t := d.Truncate(2)
	neg := t.IsNegative()
	// negative zero should be positive
	if t.IsZero() {
		neg = false
	}
	c := t.Shift(2).IntPart()
	if c < 0 {
		c = -c
	}
	frac := c % 100
	integ := (c / 100) % 10000000
	digits := make([]byte, 7)
	tmp := integ
	for i := 6; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	pat := []byte{'Z', ',', 'Z', 'Z', 'Z', ',', 'Z', 'Z', '9'}
	out := make([]byte, 0, 9)
	di := 0
	printed := false
	for _, p := range pat {
		if p == ',' {
			if printed {
				out = append(out, ',')
			} else {
				out = append(out, ' ')
			}
		} else {
			dgt := digits[di]
			di++
			if p == '9' {
				out = append(out, '0'+dgt)
				if dgt != 0 {
					printed = true
				}
			} else {
				if dgt != 0 {
					out = append(out, '0'+dgt)
					printed = true
				} else {
					if printed {
						out = append(out, '0')
					} else {
						out = append(out, ' ')
					}
				}
			}
		}
	}
	sign := byte(' ')
	if neg {
		sign = '-'
	}
	fracStr := fmt.Sprintf(".%02d", frac)
	return string([]byte{sign}) + string(out) + fracStr
}

func formatTot(d decimal.Decimal) string {
	t := d.Truncate(2)
	neg := t.IsNegative()
	if t.IsZero() {
		neg = false
	}
	c := t.Shift(2).IntPart()
	if c < 0 {
		c = -c
	}
	frac := c % 100
	integ := (c / 100) % 1000000000
	digits := make([]byte, 9)
	tmp := integ
	for i := 8; i >= 0; i-- {
		digits[i] = byte(tmp % 10)
		tmp /= 10
	}
	pat := []byte{'Z', 'Z', 'Z', ',', 'Z', 'Z', 'Z', ',', 'Z', 'Z', '9'}
	out := make([]byte, 0, 11)
	di := 0
	printed := false
	for _, p := range pat {
		if p == ',' {
			if printed {
				out = append(out, ',')
			} else {
				out = append(out, ' ')
			}
		} else {
			dgt := digits[di]
			di++
			if p == '9' {
				out = append(out, '0'+dgt)
				if dgt != 0 {
					printed = true
				}
			} else {
				if dgt != 0 {
					out = append(out, '0'+dgt)
					printed = true
				} else {
					if printed {
						out = append(out, '0')
					} else {
						out = append(out, ' ')
					}
				}
			}
		}
	}
	sign := byte(' ')
	if neg {
		sign = '-'
	}
	fracStr := fmt.Sprintf(".%02d", frac)
	return string([]byte{sign}) + string(out) + fracStr
}

func formatSkipped(v int64) string {
	m := v % 100
	if m < 0 {
		m = -m
	}
	return fmt.Sprintf("%02d", m)
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	curRec.BrBranch = line[0:2]
	curRec.BrAcct = line[2:6]
	curRec.BrType = line[6:7]
	curRec.BrAmt = parseAmt(line[7:14])
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func POSTPARA() {
	WsAmtEd = formatAmt(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(curRec.BrAmt))
		fmt.Fprintln(os.Stdout, curRec.BrAcct+" D "+WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(curRec.BrAmt))
		fmt.Fprintln(os.Stdout, curRec.BrAcct+" C "+WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Fprintln(os.Stdout, curRec.BrAcct+" ? SKIPPED")
	}
}

func ACCTBREAKPARA() {
	WsBalEd = formatBal(WsBal)
	fmt.Fprintln(os.Stdout, "  ACCOUNT "+WsPrevAcct+" BALANCE:"+WsBalEd)
	WsBranchTot = storeTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.Zero
}

func BRANCHBREAKPARA() {
	WsTotEd = formatTot(WsBranchTot)
	fmt.Fprintln(os.Stdout, " BRANCH "+WsPrevBranch+" TOTAL:"+WsTotEd)
	WsGrandTot = storeTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.Zero
}

func GRANDPARA() {
	WsTotEd = formatTot(WsGrandTot)
	fmt.Fprintln(os.Stdout, "GRAND TOTAL:"+WsTotEd)
	fmt.Fprintln(os.Stdout, "SKIPPED: "+formatSkipped(WsSkipped))
}

func main() {
	// OPEN INPUT LEDGER-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		inputLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			s := sc.Text()
			// strip trailing \r if present (Scanner strips \n, leaves \r for \r\n? actually strips \r\n)
			if len(s) > 0 && s[len(s)-1] == '\r' {
				s = s[:len(s)-1]
			}
			inputLines = append(inputLines, s)
		}
		f.Close()
	}
	inputIdx = 0
	// ensure defaults (in case)
	WsPrevBranch = padRight("", 2)
	WsPrevAcct = padRight("", 4)
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	GRANDPARA()
}
